import { NextRequest, NextResponse } from "next/server";
import { canEditCategory, getCategoryAccessScope } from "@/lib/auth/category-permissions";
import { requireAuthenticatedSessionUser, requireSessionUser, toForbiddenApiResponse, toUnauthorizedApiResponse } from "@/lib/auth/api";
import { resolveCodexAccessTokenFromRequest } from "@/lib/auth/codex-server";
import { readJsonBody } from "@/lib/network/request-body";
import { getPublishCategoryMetadata } from "@/lib/publish/publish-store";
import type { PublishCategory } from "@/lib/publish/types";
import { toStudioFailureResponse } from "@/lib/studio/error-response";
import { explodeSlidesForPop } from "@/lib/studio/frames";
import { planMissingSlideImageRequests } from "@/lib/studio/image-query-planner";
import { planManualImageScenePrompts } from "@/lib/studio/manual-image-scene-planner";
import { resolveStudioCharacterProfileById } from "@/lib/studio/character-profiles";
import { withoutAutomaticImageProfileFields } from "@/lib/studio/image-mode-profile";
import { applyImagePolicy } from "@/lib/studio/policy";
import { parsePrepareRequest } from "@/lib/studio/validation";
import {
  isStudioAutoGeneratedImageSource,
  isStudioGeneratedImageSource,
  type StudioPrepareResponse,
} from "@/types/studio-json";

export const runtime = "nodejs";

type StudioPrepareStage = "full" | "plan" | "resolve";
type StudioResolvedProjectProfileMetadata = Awaited<ReturnType<typeof getPublishCategoryMetadata>>;

type StudioPrepareRouteDependencies = {
  requireSessionUser: typeof requireSessionUser;
  requireAuthenticatedSessionUser: typeof requireAuthenticatedSessionUser;
  toForbiddenApiResponse: typeof toForbiddenApiResponse;
  toUnauthorizedApiResponse: typeof toUnauthorizedApiResponse;
  getCategoryAccessScope: typeof getCategoryAccessScope;
  canEditCategory: typeof canEditCategory;
  resolveCodexAccessTokenFromRequest: typeof resolveCodexAccessTokenFromRequest;
  getPublishCategoryMetadata: typeof getPublishCategoryMetadata;
  readJsonBody: typeof readJsonBody;
  toStudioFailureResponse: typeof toStudioFailureResponse;
  explodeSlidesForPop: typeof explodeSlidesForPop;
  planMissingSlideImageRequests: typeof planMissingSlideImageRequests;
  planManualImageScenePrompts: typeof planManualImageScenePrompts;
  applyImagePolicy: typeof applyImagePolicy;
  parsePrepareRequest: typeof parsePrepareRequest;
  now: () => number;
  logInfo: (message: string) => void;
};

export const defaultStudioPrepareRouteDependencies: StudioPrepareRouteDependencies = {
  requireSessionUser,
  requireAuthenticatedSessionUser,
  toForbiddenApiResponse,
  toUnauthorizedApiResponse,
  getCategoryAccessScope,
  canEditCategory,
  resolveCodexAccessTokenFromRequest,
  getPublishCategoryMetadata,
  readJsonBody,
  toStudioFailureResponse,
  explodeSlidesForPop,
  planMissingSlideImageRequests,
  planManualImageScenePrompts,
  applyImagePolicy,
  parsePrepareRequest,
  now: () => Date.now(),
  logInfo: (message) => console.info(message),
};

function isPromptPlannedImageMode(source: string | undefined): boolean {
  return isStudioGeneratedImageSource(source);
}

function buildPromptImageModeWarning(source: string | undefined): string {
  return isStudioAutoGeneratedImageSource(source)
    ? "AI 이미지(자동 생성) 모드: prepare 후 이미지 없는 슬라이드만 Codex가 생성해 자동 첨부합니다."
    : "AI 이미지(수동 생성) 모드: ChatGPT 웹에 프롬프트를 붙여 넣어 정사각형 이미지를 만든 뒤 슬라이드에 업로드하거나 내 자산에서 적용하세요.";
}

function prepareSlidesForPromptImageMode(
  slides: Parameters<typeof defaultStudioPrepareRouteDependencies["explodeSlidesForPop"]>[0]
) {
  return slides.map((slide) => ({
    ...slide,
    resolvedImageUrl: slide.resolvedImageUrl || slide.imageUrl,
    resolvedBy: slide.resolvedBy || (slide.imageUrl ? ("direct" as const) : undefined),
  }));
}

async function resolveProjectProfileMetadata(
  payload: ReturnType<typeof defaultStudioPrepareRouteDependencies["parsePrepareRequest"]>,
  deps: StudioPrepareRouteDependencies,
  userId: string,
  publishCategory: string,
  preferLatest: boolean
): Promise<StudioResolvedProjectProfileMetadata | null> {
  const snapshotMetadata = payload.projectProfileSnapshot?.contentProfile.metadataSnapshot || null;
  if (!preferLatest && snapshotMetadata) return snapshotMetadata;
  const latest = publishCategory
    ? await deps.getPublishCategoryMetadata(userId, publishCategory).catch(() => null)
    : null;
  return preferLatest
    ? latest || snapshotMetadata
    : snapshotMetadata || latest;
}

async function prepareManualImagePromptSlides(
  payload: ReturnType<typeof defaultStudioPrepareRouteDependencies["parsePrepareRequest"]>,
  deps: StudioPrepareRouteDependencies,
  options: {
    userId: string;
    stage: StudioPrepareStage;
    imageSource?: string;
    codexAccessToken?: string;
  }
): Promise<{ slides: typeof payload.slides; warnings: string[] }> {
  const warnings: string[] = [buildPromptImageModeWarning(options.imageSource)];

  if (options.stage === "resolve") {
    return {
      slides: payload.slides,
      warnings,
    };
  }

  const publishCategory = payload.publishCategory || "default";
  const requestedFixedCharacterProfileId = String(payload.fixedCharacterProfileId || "").trim();
  const metadata = await resolveProjectProfileMetadata(
    payload,
    deps,
    options.userId,
    publishCategory,
    Boolean(requestedFixedCharacterProfileId)
  );
  const selectedFixedCharacterProfile = resolveStudioCharacterProfileById(
    metadata?.fixedCharacterProfiles,
    requestedFixedCharacterProfileId
  );
  if (requestedFixedCharacterProfileId && !selectedFixedCharacterProfile) {
    warnings.push(
      "선택한 고정 캐릭터가 현재 콘텐츠 프로필에 없어 선택 안 함으로 처리했습니다."
    );
  }
  const promptMetadata = withoutAutomaticImageProfileFields(metadata);
  const planningSlides = selectedFixedCharacterProfile
    ? payload.slides.map((slide) => ({
        ...slide,
        characterIds: [selectedFixedCharacterProfile.characterId],
      }))
    : payload.slides;

  const planned = await deps.planManualImageScenePrompts(
    {
      publishCategory,
      slides: planningSlides,
      metadata: promptMetadata,
      characterProfiles: selectedFixedCharacterProfile
        ? [selectedFixedCharacterProfile]
        : options.imageSource === "auto-ai-generate"
          ? payload.characterProfiles
          : undefined,
      imageStylePrompt: selectedFixedCharacterProfile
        ? undefined
        : payload.imageStylePrompt,
      preferStyleOnlyBasePrompt: true,
      codexModel: payload.codexModel,
    },
    {
      codexAccessToken: options.codexAccessToken,
    }
  );

  return {
    slides: payload.slides.map((slide, slideIndex) => ({
      ...(() => {
        const plannedPrompt = planned.items.find((item) => item.slideIndex === slideIndex);
        if (!plannedPrompt) return slide;
        const { slideIndex: _slideIndex, ...manualImagePrompt } = plannedPrompt;
        const resolvedCharacterIds =
          selectedFixedCharacterProfile
            ? [selectedFixedCharacterProfile.characterId]
            : Array.isArray(slide.characterIds) && slide.characterIds.length > 0
            ? slide.characterIds
            : manualImagePrompt.characterIds;
        return {
          ...slide,
          characterIds: Array.isArray(resolvedCharacterIds) && resolvedCharacterIds.length > 0 ? resolvedCharacterIds : undefined,
          manualImagePrompt,
        };
      })(),
    })),
    warnings: [...planned.warnings, ...warnings],
  };
}

function resolvePrepareStage(request: NextRequest): StudioPrepareStage {
  const raw = String(request.nextUrl.searchParams.get("stage") || "")
    .trim()
    .toLowerCase();
  if (raw === "plan" || raw === "resolve") return raw;
  return "full";
}

function extractPublishCategoryForAuthorization(body: unknown): PublishCategory | undefined {
  if (!body || typeof body !== "object" || Array.isArray(body)) return undefined;
  const value = (body as Record<string, unknown>).publishCategory;
  return typeof value === "string" && value.trim() ? (value.trim() as PublishCategory) : undefined;
}

export async function handleStudioPreparePost(
  request: NextRequest,
  deps: StudioPrepareRouteDependencies = defaultStudioPrepareRouteDependencies
) {
  const user = deps.requireSessionUser(request);
  if (!user) return deps.toUnauthorizedApiResponse();
  const authUser = deps.requireAuthenticatedSessionUser(request) || user;
  try {
    const startedAt = deps.now();
    const stage = resolvePrepareStage(request);
    deps.logInfo("[studio-prepare] request_received");
    const body = await deps.readJsonBody(request);
    const publishCategory = extractPublishCategoryForAuthorization(body);
    const scope = await deps.getCategoryAccessScope({
      actorRole: authUser.role === "admin" ? "admin" : "member",
      workspaceUserId: user.id,
    });
    if (!deps.canEditCategory(scope, publishCategory)) {
      return deps.toForbiddenApiResponse("편집 권한이 있는 고객(category)만 제작할 수 있습니다.");
    }
    const payload = deps.parsePrepareRequest(body);
    deps.logInfo(
      `[studio-prepare] payload_parsed stage=${stage} slides=${payload.slides.length} category=${payload.publishCategory || "default"}`
    );
    payload.libraryUserScope = user.id;
    if (isPromptPlannedImageMode(payload.imagePolicy.source)) {
      const promptStartedAt = deps.now();
      const codexAccessToken =
        stage === "plan" || stage === "full" ? await deps.resolveCodexAccessTokenFromRequest(request) : undefined;
      const manualPrepared = await prepareManualImagePromptSlides(payload, deps, {
        userId: user.id,
        stage,
        imageSource: payload.imagePolicy.source,
        codexAccessToken,
      });
      if (stage === "plan") {
        const totalMs = Math.max(0, deps.now() - startedAt);
        deps.logInfo(
          `[studio-prepare] stage=plan prompt-image source=${payload.imagePolicy.source} slides=${payload.slides.length} total_ms=${totalMs}`
        );
        const response: StudioPrepareResponse = {
          ok: true,
          warnings: [
            `[timing] prepare_plan prompt_ms=${Math.max(0, deps.now() - promptStartedAt)} total_ms=${totalMs}`,
            ...manualPrepared.warnings,
          ],
          slides: manualPrepared.slides,
          usage: {
            imagePolicyMs: 0,
          },
        };
        return NextResponse.json(response);
      }

      const preparedSlides = prepareSlidesForPromptImageMode(manualPrepared.slides);
      const resolvedSlides = deps.explodeSlidesForPop(preparedSlides);
      const totalMs = Math.max(0, deps.now() - startedAt);
      if (stage === "resolve") {
        deps.logInfo(
          `[studio-prepare] stage=resolve prompt-image source=${payload.imagePolicy.source} slides=${payload.slides.length} total_ms=${totalMs}`
        );
        const response: StudioPrepareResponse = {
          ok: true,
          warnings: [
            `[timing] prepare_resolve prompt_ms=${Math.max(0, deps.now() - promptStartedAt)} total_ms=${totalMs}`,
            ...manualPrepared.warnings,
          ],
          slides: resolvedSlides,
          usage: {
            imagePolicyMs: 0,
          },
        };
        return NextResponse.json(response);
      }

      deps.logInfo(
        `[studio-prepare] stage=full prompt-image source=${payload.imagePolicy.source} slides=${payload.slides.length} total_ms=${totalMs}`
      );
      return NextResponse.json({
        ok: true,
        warnings: [
          `[timing] prepare prompt_ms=${Math.max(0, deps.now() - promptStartedAt)} total_ms=${totalMs}`,
          ...manualPrepared.warnings,
        ],
        slides: resolvedSlides,
        usage: {
          imagePolicyMs: 0,
        },
      } satisfies StudioPrepareResponse);
    }

    if (stage === "plan") {
      const codexAccessToken = await deps.resolveCodexAccessTokenFromRequest(request);
      const plannerStartedAt = deps.now();
      const plannedImage = await deps.planMissingSlideImageRequests(payload, { codexAccessToken, bestEffort: true });
      const plannerMs = Math.max(0, deps.now() - plannerStartedAt);
      const totalMs = Math.max(0, deps.now() - startedAt);
      deps.logInfo(`[studio-prepare] stage=plan slides=${payload.slides.length} planner_ms=${plannerMs} total_ms=${totalMs}`);
      const response: StudioPrepareResponse = {
        ok: true,
        warnings: [`[timing] prepare_plan planner_ms=${plannerMs} total_ms=${totalMs}`, ...plannedImage.warnings],
        slides: plannedImage.payload.slides,
        usage: {
          imagePolicyMs: 0,
        },
      };
      return NextResponse.json(response);
    }

    if (stage === "resolve") {
      const policyStartedAt = deps.now();
      const resolved = await deps.applyImagePolicy(payload);
      const policyMs = Math.max(0, deps.now() - policyStartedAt);
      const totalMs = Math.max(0, deps.now() - startedAt);
      deps.logInfo(`[studio-prepare] stage=resolve slides=${payload.slides.length} policy_ms=${policyMs} total_ms=${totalMs}`);
      const response: StudioPrepareResponse = {
        ok: true,
        warnings: [`[timing] prepare_resolve policy_ms=${policyMs} total_ms=${totalMs}`, ...resolved.warnings],
        slides: deps.explodeSlidesForPop(resolved.slides),
        usage: {
          imagePolicyMs: totalMs,
        },
      };
      return NextResponse.json(response);
    }

    const codexAccessToken = await deps.resolveCodexAccessTokenFromRequest(request);
    const plannerStartedAt = deps.now();
    const plannedImage = await deps.planMissingSlideImageRequests(payload, { codexAccessToken, bestEffort: true });
    const plannerMs = Math.max(0, deps.now() - plannerStartedAt);
    const policyStartedAt = deps.now();
    const resolved = await deps.applyImagePolicy(plannedImage.payload);
    const policyMs = Math.max(0, deps.now() - policyStartedAt);
    const totalMs = Math.max(0, deps.now() - startedAt);
    const timingWarnings = [`[timing] prepare planner_ms=${plannerMs} policy_ms=${policyMs} total_ms=${totalMs}`];
    deps.logInfo(
      `[studio-prepare] stage=full slides=${payload.slides.length} planner_ms=${plannerMs} policy_ms=${policyMs} total_ms=${totalMs}`
    );
    return NextResponse.json({
      ok: true,
      warnings: [...timingWarnings, ...plannedImage.warnings, ...resolved.warnings],
      slides: deps.explodeSlidesForPop(resolved.slides),
      usage: {
        imagePolicyMs: Math.max(0, deps.now() - startedAt),
      },
    } satisfies StudioPrepareResponse);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return deps.toStudioFailureResponse(message, "INVALID_PREPARE_INPUT", "PREPARE_FAILED");
  }
}

export async function POST(request: NextRequest) {
  return handleStudioPreparePost(request);
}
